let todos = [];

async function init() {
  const saved = await __amiba__.storage.get('todos');
  if (saved) todos = saved;
  renderList();
}

function renderList() {
  const container = document.getElementById('list_container');
  if (!container) return;
  container.innerHTML = todos.map((t, i) =>
    '<div style="display:flex;align-items:center;padding:8px;background:#f5f5f5;border-radius:8px;margin-bottom:4px">' +
    '<span style="flex:1;text-decoration:' + (t.done ? 'line-through' : 'none') + '">' + t.text + '</span>' +
    '<button onclick="handleToggle(' + i + ')" style="margin-right:4px;padding:4px 8px;border:1px solid #ccc;border-radius:4px;background:white;cursor:pointer">OK</button>' +
    '<button onclick="handleDelete(' + i + ')" style="padding:4px 8px;border:1px solid #ccc;border-radius:4px;background:white;cursor:pointer">X</button>' +
    '</div>'
  ).join('');
}

async function handleAdd() {
  const input = document.getElementById('todo_input');
  const val = input?.value?.trim();
  if (!val) return;
  todos.push({ text: val, done: false });
  await __amiba__.storage.set('todos', todos);
  input.value = '';
  renderList();
  __amiba__.showToast('已添加', 'success');
}

async function handleToggle(i) {
  todos[i].done = !todos[i].done;
  await __amiba__.storage.set('todos', todos);
  renderList();
}

async function handleDelete(i) {
  todos.splice(i, 1);
  await __amiba__.storage.set('todos', todos);
  renderList();
}

init();
